# Initially generated by GitHub Copilot.
"""Structured change-operation dataclasses for MAM-parsed-plus diffs.

Each dataclass represents one atomic change that the diff pipeline can
describe.  Two families:

  Text-level ops   — operate on flattened Unicode body text
  Structural ops   — operate on the EP template tree

The ChangeOps serve as the single intermediate representation between
raw diffing and English rendering, and are also consumed by the
roundtrip verifier (change_ops_apply → mpplus_verify).

EVERY OP THAT PLACES A MARK RECORDS WHERE IN ITS CLUSTER THE MARK GOES.
A position is the index the mark has among the combining marks of its
letter's grapheme cluster in the new text, counting every combining mark
there, not only the marks of the class being compared.  The English
rendering never reads a position; change_ops_apply needs one, because
MAM-normal order (mb_cmn.uni_denorm.give_std_mark_order) fixes the place
of only four marks, the shin dot, the sin dot, the dagesh or mapiq, and
the rafe, so where any other placed mark goes is data that nothing else
can recover.  Until 2026-09-11 no op recorded it, and every placement
appended the mark to the end of its cluster.  Isaiah 24:18 is the case
that showed it.  Since MAM-basics 209b4c05 the verse's first cluster has
U+05BD HEBREW POINT METEG between U+05B0 HEBREW POINT SHEVA and U+05A0
HEBREW ACCENT TELISHA GEDOLA.  Appending put the meteg after the accent,
the roundtrip verifier rejected the result, and every mega run stopped
at its mpplus diff step.  That is finding 1 of the 2026-09-10 review.

A removal records no position: it takes the first occurrence of its mark
in the cluster, which is exact for every cluster that has no mark twice.
"""

from dataclasses import dataclass
from typing import Optional

# ── Text-level ops ───────────────────────────────────────────


@dataclass(frozen=True)
class MarkRemoved:
    """A combining mark was removed from a specific letter."""

    char: str
    on_letter: str
    letter_occurrence: int


@dataclass(frozen=True)
class MarkAdded:
    """A combining mark was added to a specific letter."""

    char: str
    on_letter: str
    letter_occurrence: int
    position: int  # the mark's index in its cluster in the new text


@dataclass(frozen=True)
class MarkMoved:
    """The same mark moved from one letter to another."""

    char: str
    from_letter: str
    from_occurrence: int
    to_letter: str
    to_occurrence: int
    to_position: int  # the mark's index in its cluster in the new text


@dataclass(frozen=True)
class MarkReplaced:
    """One mark was replaced by a different mark on the same letter."""

    on_letter: str
    letter_occurrence: int
    old_char: str
    new_char: str
    new_position: int  # new_char's index in its cluster in the new text


@dataclass(frozen=True)
class GenericReplace:
    """Both mark and letter differ — a catch-all 1:1 replace."""

    old_char: str
    old_letter: str
    old_occurrence: int
    new_char: str
    new_letter: str
    new_occurrence: int
    new_position: int  # new_char's index in its cluster in the new text


@dataclass(frozen=True)
class ComplexReplace:
    """Multi-char replace that cannot be decomposed further."""

    old_qualified: tuple  # tuple of (char, letter, occ) triples
    new_qualified: tuple
    new_positions: tuple  # each new_qualified mark's index in its new cluster


@dataclass(frozen=True)
class MarkReordered:
    """Marks on the same letter appear in a different order."""

    chars: tuple  # tuple of mark characters in old order
    on_letter: str
    letter_occurrence: int
    new_positions: tuple  # each of chars' index in the cluster in the new text


@dataclass(frozen=True)
class GrayMaqafAdded:
    """A space was replaced by a gray maqaf."""

    pass


@dataclass(frozen=True)
class GrayMaqafRemoved:
    """A gray maqaf was replaced by a space."""

    pass


@dataclass(frozen=True)
class PaseqAdded:
    """A paseq or legarmeh was added."""

    paseq_type: str  # "legarmeh" or "paseq" or "paseq / legarmeh"
    on_word: Optional[str] = None
    word_occurrence: Optional[int] = None
    old_fragment: Optional[str] = None
    new_fragment: Optional[str] = None


@dataclass(frozen=True)
class PaseqRemoved:
    """A paseq or legarmeh was removed."""

    paseq_type: str
    on_word: Optional[str] = None
    word_occurrence: Optional[int] = None
    old_fragment: Optional[str] = None
    new_fragment: Optional[str] = None


@dataclass(frozen=True)
class GenericTextReplace:
    """Fallback: a text fragment was replaced.

    Passes the roundtrip check trivially (it is literally "replace X
    with Y") but signals that the diff was not fully decomposed.
    """

    old_fragment: str
    new_fragment: str


# ── Structural ops ───────────────────────────────────────────


@dataclass(frozen=True)
class TemplateAdded:
    """A template was added to the EP tree."""

    name: str


@dataclass(frozen=True)
class TemplateRemoved:
    """A template was removed from the EP tree."""

    name: str


@dataclass(frozen=True)
class TemplateRestructured:
    """Internal template structure changed (same names, different arrangement)."""

    pass


# ── Helpers ──────────────────────────────────────────────────


def is_text_op(op):
    """True if *op* is a text-level ChangeOp."""
    return isinstance(
        op,
        (
            MarkRemoved,
            MarkAdded,
            MarkMoved,
            MarkReplaced,
            GenericReplace,
            ComplexReplace,
            MarkReordered,
            GrayMaqafAdded,
            GrayMaqafRemoved,
            PaseqAdded,
            PaseqRemoved,
            GenericTextReplace,
        ),
    )


def is_structural_op(op):
    """True if *op* is a structural ChangeOp."""
    return isinstance(op, (TemplateAdded, TemplateRemoved, TemplateRestructured))
